"""Label dictionary, Markdown glossary and JSON-LD (RDFS plus SKOS) export."""

from __future__ import annotations

import json
from typing import Any

from hai_ontology.codegen.common import header
from hai_ontology.meta import Manifest

BASE = "https://humaital.com/ontology/hai#"


def labels(manifest: Manifest) -> dict[str, Any]:
    return {
        "x-generated": "generated by hai-ontology from the manifest under ontology/. Do not edit.",
        "x-manifest-hash": manifest.hash,
        "ontology_version": manifest.ontology_version,
        "methodology_version": manifest.methodology_version,
        "product": manifest.methodology.product.model_dump(),
        "vocabularies": {
            code: {v.code: {"label": v.label, "description": v.description} for v in voc.values}
            for code, voc in sorted(manifest.vocabularies.items())
        },
        "entities": {
            e.name: {"label": e.name, "table": e.table, "description": e.description} for e in manifest.entities
        },
        "pillars": {p.code: {"label": p.name, "description": p.description} for p in manifest.pillars},
        "criteria": {
            c.code: {"label": c.name, "description": c.definition, "pillar": c.pillar} for c in manifest.criteria
        },
        "integrity_constraints": {ic.id: ic.rule for ic in manifest.ontology.integrity_constraints},
        "coverage_wording": {
            v.code: v.attributes["report_wording"] for v in manifest.vocabularies["coverage_state"].values
        },
    }


def render_labels(manifest: Manifest) -> str:
    return json.dumps(labels(manifest), indent=2, sort_keys=False, ensure_ascii=True) + "\n"


def glossary(manifest: Manifest) -> str:
    out = ["<!--\n" + header(manifest, "   ") + "-->\n\n"]
    out.append("# HAI Ontology Glossary\n\n")
    out.append(
        f"Ontology {manifest.ontology_version}, methodology {manifest.methodology_version}, "
        f"ruleset {manifest.ruleset.version}. Rebuilt on every change to the manifest.\n\n"
    )
    out.append("## Layers And Entities\n\n")
    for layer in manifest.ontology.layers:
        out.append(f"### {layer.title}\n\n{layer.description}\n\n")
        out.append("| Entity | Table | Mutability | Writers | Description |\n|---|---|---|---|---|\n")
        for e in manifest.entities:
            if e.layer == layer.code:
                out.append(f"| {e.name} | `{e.table}` | {e.mutability} | {', '.join(e.writers)} | {e.description} |\n")
        out.append("\n")
    out.append("## Fields\n\n")
    for e in manifest.entities:
        out.append(f"### {e.name}\n\n| Field | Type | Required | Description |\n|---|---|---|---|\n")
        for f in e.all_fields:
            typ: str = str(f.type)
            if f.vocabulary:
                typ = f"{typ} ({f.vocabulary})"
            if f.ref:
                typ = f"ref ({f.ref})"
            if f.type == "array":
                typ = f"array of {f.items}" + (f" ({f.vocabulary})" if f.vocabulary else "")
            flags = "yes" if f.required else "no"
            if f.immutable:
                flags += ", immutable"
            out.append(f"| `{f.name}` | {typ} | {flags} | {f.description} |\n")
        out.append("\n")
    out.append(
        "## Relations\n\n| Relation | From | To | Cardinality | Time-bound | Description |\n|---|---|---|---|---|---|\n"
    )
    for r in manifest.ontology.relations:
        out.append(
            f"| {r.name} | {r.from_entity} | {', '.join(r.to)} | {r.cardinality} | {'yes' if r.time_bound else 'no'} | {r.description} |\n"  # noqa: E501
        )
    out.append("\n## Vocabularies\n\n")
    for code in sorted(manifest.vocabularies):
        voc = manifest.vocabularies[code]
        tag = " (derived)" if voc.derived else ""
        out.append(
            f"### {voc.title} (`{code}`){tag}\n\n{voc.description}\n\n| Code | Label | Description |\n|---|---|---|\n"
        )
        for v in voc.ordered_values:
            out.append(f"| `{v.code}` | {v.label} | {v.description} |\n")
        out.append("\n")
    out.append(
        "## Pillars And Criteria\n\n| Code | Pillar | Name | Materiality | Weight | Freshness (months) | Status |\n|---|---|---|---|---|---|---|\n"  # noqa: E501
    )
    for c in manifest.criteria:
        out.append(
            f"| {c.code} | {c.pillar} | {c.name} | {c.materiality} ({c.materiality_weight}) | {c.weight} | {c.freshness_window_months} | {c.content_status} |\n"  # noqa: E501
        )
    out.append("\n## Rules\n\n| Code | Kind | Scope | Order | Description |\n|---|---|---|---|---|\n")
    for rule in sorted(manifest.ruleset.rules, key=lambda x: (x.scope != "criterion", x.run_order)):
        out.append(f"| {rule.code} | {rule.kind} | {rule.scope} | {rule.run_order} | {rule.description} |\n")
    out.append(
        "\n## Integrity Constraints\n\n| Id | Rule | Enforced in | Implementation | Acceptance test |\n|---|---|---|---|---|\n"  # noqa: E501
    )
    for ic in manifest.ontology.integrity_constraints:
        out.append(f"| {ic.id} | {ic.rule} | {ic.enforced_in} | {ic.implementation} | {ic.acceptance_test} |\n")
    out.append("\n## Acceptance Tests\n\n| Id | Title | Tests |\n|---|---|---|\n")
    for at in manifest.ontology.acceptance_tests:
        out.append(f"| {at.id} | {at.title} | {', '.join(f'`{t}`' for t in at.tests)} |\n")
    return "".join(out)


def jsonld(manifest: Manifest) -> dict[str, Any]:
    graph: list[dict[str, Any]] = []
    graph.append(
        {
            "@id": BASE.rstrip("#"),
            "@type": "owl:Ontology",
            "rdfs:label": manifest.ontology.ontology.title,
            "rdfs:comment": manifest.ontology.ontology.description,
            "owl:versionInfo": manifest.ontology_version,
            "hai:methodologyVersion": manifest.methodology_version,
            "hai:manifestHash": manifest.hash,
        }
    )
    for layer in manifest.ontology.layers:
        graph.append(
            {
                "@id": f"{BASE}layer/{layer.code}",
                "@type": "rdfs:Class",
                "rdfs:label": layer.title,
                "rdfs:comment": layer.description,
            }
        )
    for e in manifest.entities:
        graph.append(
            {
                "@id": f"{BASE}{e.name}",
                "@type": "rdfs:Class",
                "rdfs:label": e.name,
                "rdfs:comment": e.description,
                "rdfs:subClassOf": {"@id": f"{BASE}layer/{e.layer}"},
                "hai:table": e.table,
                "hai:mutability": e.mutability,
            }
        )
        for f in e.all_fields:
            prop: dict[str, Any] = {
                "@id": f"{BASE}{e.name}/{f.name}",
                "@type": "rdf:Property",
                "rdfs:label": f.name,
                "rdfs:comment": f.description,
                "rdfs:domain": {"@id": f"{BASE}{e.name}"},
            }
            if f.ref:
                prop["rdfs:range"] = {"@id": f"{BASE}{f.ref}"}
            elif f.vocabulary:
                prop["rdfs:range"] = {"@id": f"{BASE}vocab/{f.vocabulary}"}
            else:
                prop["rdfs:range"] = {"@id": f"xsd:{_xsd(f.type)}"}
            graph.append(prop)
    for r in manifest.ontology.relations:
        graph.append(
            {
                "@id": f"{BASE}rel/{r.name}",
                "@type": "rdf:Property",
                "rdfs:label": r.name,
                "rdfs:comment": r.description,
                "rdfs:domain": {"@id": f"{BASE}{r.from_entity}"},
                "rdfs:range": [{"@id": f"{BASE}{t}"} for t in r.to],
                "hai:cardinality": r.cardinality,
                "hai:timeBound": r.time_bound,
            }
        )
    for code in sorted(manifest.vocabularies):
        voc = manifest.vocabularies[code]
        graph.append(
            {
                "@id": f"{BASE}vocab/{code}",
                "@type": "skos:ConceptScheme",
                "skos:prefLabel": voc.title,
                "skos:definition": voc.description,
                "hai:derived": voc.derived,
                "skos:hasTopConcept": [{"@id": f"{BASE}vocab/{code}/{v.code}"} for v in voc.ordered_values],
            }
        )
        for v in voc.ordered_values:
            concept: dict[str, Any] = {
                "@id": f"{BASE}vocab/{code}/{v.code}",
                "@type": "skos:Concept",
                "skos:inScheme": {"@id": f"{BASE}vocab/{code}"},
                "skos:notation": v.code,
                "skos:prefLabel": v.label,
                "skos:definition": v.description,
            }
            if v.aliases:
                concept["skos:altLabel"] = list(v.aliases)
            if v.rank is not None:
                concept["hai:rank"] = v.rank
            if v.attributes:
                concept["hai:attributes"] = v.attributes
            graph.append(concept)
    for ic in manifest.ontology.integrity_constraints:
        graph.append(
            {
                "@id": f"{BASE}ic/{ic.id}",
                "@type": "hai:IntegrityConstraint",
                "rdfs:label": ic.id,
                "rdfs:comment": ic.rule,
                "hai:enforcedIn": ic.enforced_in,
                "hai:acceptanceTest": ic.acceptance_test,
            }
        )
    return {
        "@context": {
            "hai": BASE,
            "rdf": "http://www.w3.org/1999/02/22-rdf-syntax-ns#",
            "rdfs": "http://www.w3.org/2000/01/rdf-schema#",
            "owl": "http://www.w3.org/2002/07/owl#",
            "skos": "http://www.w3.org/2004/02/skos/core#",
            "xsd": "http://www.w3.org/2001/XMLSchema#",
        },
        "@graph": graph,
    }


def _xsd(t: str) -> str:
    return {
        "uuid": "string",
        "text": "string",
        "int": "integer",
        "bigint": "long",
        "numeric": "decimal",
        "bool": "boolean",
        "timestamp": "dateTime",
        "date": "date",
        "json": "string",
        "enum": "string",
        "ref": "string",
        "array": "string",
    }[t]


def render_jsonld(manifest: Manifest) -> str:
    return json.dumps(jsonld(manifest), indent=2, ensure_ascii=True) + "\n"
